 const [searchFrom,setSearchFrom]=useState('today');const [vocabFocus,setVocabFocus]=useState(false);const [checkinError,setCheckinError]=useState('');const [settingsError,setSettingsError]=useState('');
 const recordingRequest=useRef(0);const recordingScope=useRef({owner,nav,tab:trainingTab,alive:true});recordingScope.current={owner,nav,tab:trainingTab,alive:true};
 useEffect(()=>{recordingScope.current.alive=true;return()=>{recordingScope.current.alive=false;recordingRequest.current++;};},[]);
 useEffect(()=>{recordingRequest.current++;setRecordingPlay(null);},[owner,nav,trainingTab]);
