 const launchPractice=(selected:Question[],chainId?:string)=>{if(!selected.length)return;if(!practiceWorkflow.ready){toast.error(practiceWorkflow.error||'练习会话正在读取，请稍后重试。');return;}const authoredUnits=new Map(practiceUnits(questions).map(unit=>[unit.id,unit.questions]));const full=practiceUnits(selected).flatMap(unit=>authoredUnits.get(unit.id)||[]);void practiceWorkflow.start(full,{unitIds:practiceUnits(full).map(unit=>unit.id),chainId,initialSeenQids:data.attempts.map(attempt=>attempt.qid)}).then(result=>{if(result.status==='blocked'||result.status==='conflict'||result.status==='pending'||result.status==='unknown')toast.error(result.reason);});};
 const selectAndStart=(intent:'continue'|'custom'|'wrong'|'review',part?:number,count=5,chainId?:string)=>{try{const excluded=intent==='continue'&&chainId?practiceWorkflow.sessions.filter(session=>session.chainId===chainId).flatMap(session=>session.unitIds):[];const selected=selectPractice(questions,data.attempts,{intent,part,targetCount:count,excludeUnitIds:excluded});if(selected.kind==='exhausted'){toast.message(intent==='continue'?'这条练习链已无未做新题。可以换专项，或明确选择自选复练。':'当前没有匹配的题目。');return false;}launchPractice(selected.questions,chainId);return true;}catch(error){toast.error(error instanceof Error?error.message:'请检查目标题数。');return false;}};
