 const startDaily=(minimum=false)=>{const q=minimum?chooseQuestions(questions,data.attempts,listeningPart<=2?listeningPart:2,1):[...chooseQuestions(questions,data.attempts,listeningPart,Math.max(1,Math.round(profile.dailyMinutes/12))),...chooseQuestions(questions,data.attempts,readingPart,Math.max(2,Math.round(profile.dailyMinutes/8)))];launchPractice(q);};
 const finish=(n:number)=>{setSpeaking(null);setMinutes(String(n));setNote('');setSelectedResource(null);setLoad('刚好');setCheckinError('');setCheckinOpen(true);};
 const openSpeaking=(prompt:Speaking|null)=>{if(recoveryClip?.processing){toast.message('录音正在整理，请稍候恢复。');return;}if(recoveryClip){setSpeaking(recoveryClip.prompt);toast.message('请先处理当前账号尚未保存的录音。');return;}setSpeaking(prompt);};
 const playRecording=async(r:Recording)=>{const request=++recordingRequest.current;const scope={...recordingScope.current};try{const url=await recordingUrl(r);recordingMediaTrace('source-ready',url,null,request);const latest=recordingScope.current;if(!latest.alive||request!==recordingRequest.current||scope.owner!==latest.owner||latest.nav!=='train'||latest.tab!=='speaking'){recordingMediaTrace('url-discarded',url,null,request);if(url.startsWith('blob:'))URL.revokeObjectURL(url);throw Error('录音回放已取消，请在当前录音列表重试。');}setRecordingPlay({url,title:r.title,recording:r,request});}catch(e){if(recordingScope.current.alive&&request===recordingRequest.current&&scope.owner===recordingScope.current.owner&&recordingScope.current.nav==='train'&&recordingScope.current.tab==='speaking')toast.error(e instanceof Error?e.message:'录音暂时无法读取，请稍后重试');throw e;}};
 const changeTheme=(t:string)=>{if(!saveTheme(t as Theme))return;if(!themeOpen)toast.success('主题已切换');};
