 const navigate=(next:string)=>{if(queue||speaking||mockOpen||practiceLookup||practiceSettlementId)return;setVocabFocus(false);setNav(next);window.scrollTo({top:0});const {lanternVocabularyView,lanternPracticeView,lanternSpeakingView,lanternPracticeLookup,...state}=window.history.state||{};window.history.pushState({...state,lanternWorkspaceView:next},'');};
 const restoreLookupFocus=(focus:HTMLElement|null)=>requestAnimationFrame(()=>{const target=focus?.isConnected&&!focus.hasAttribute?.('disabled')?focus:document.querySelector<HTMLElement>('[data-workflow-origin],#workspace-main');target?.focus({preventScroll:true});});
