 useEffect(()=>{const pop=(event:PopStateEvent)=>{if(consumedLookupPop.current){consumedLookupPop.current=false;event.stopImmediatePropagation?.();return;}const lookup=lookupRef.current;if(lookup&&event.state?.lanternPracticeLookup!==lookup.token){event.stopImmediatePropagation?.();lookupReturnRef.current=lookup;lookupRef.current=null;setPracticeLookup(null);window.scrollTo(0,lookup.scroll);restoreLookupFocus(lookup.focus);}};window.addEventListener('popstate',pop,true);return()=>window.removeEventListener('popstate',pop,true);},[]);
 const restoreSearchOrigin=(next:string)=>{const saved=searchOrigin.current;if(!saved||next!==saved.nav)return;requestAnimationFrame(()=>{window.scrollTo(0,saved.scroll);const matches=[...document.querySelectorAll<HTMLElement>('button,a,input,select,textarea')].filter(e=>e.tagName===saved.focusTag&&e.getAttribute('aria-label')===saved.focusLabel&&(e.textContent||'')===saved.focusText);const candidate=saved.focus?.isConnected?saved.focus:matches.at(Math.max(0,saved.focusIndex));const visible=(element:HTMLElement|undefined|null)=>!!element&&(typeof element.getClientRects!=='function'||element.getClientRects().length>0);const target=visible(candidate)?candidate:saved.searchTrigger?document.querySelector<HTMLElement>('.workspace-search-entry'):matches.find(visible);target?.focus({preventScroll:true});});};
 const returnFromSearch=()=>{setVocabFocus(false);setNav(searchFrom);if(window.history.state?.lanternWorkspaceView==='search'){consumedSearchPop.current=true;window.history.back();}else window.history.replaceState({...window.history.state,lanternWorkspaceView:searchFrom},'');restoreSearchOrigin(searchFrom);};
 const openSearch=()=>{if(queue||speaking||mockOpen||practiceLookup||practiceSettlementId||vocabFocus||checkinOpen||settings||themeOpen||installOpen||recordingPlay){toast.message('请先返回学习页面，再查词。');return false;}if(nav==='search'){document.querySelector<HTMLInputElement>('.vocab-redesign input[type=search]')?.focus();return true;}const originFocus=document.activeElement instanceof HTMLElement?document.activeElement:null;searchOrigin.current={nav,scroll:window.scrollY,focus:originFocus,focusTag:originFocus?.tagName||'',focusLabel:originFocus?.getAttribute('aria-label')??null,focusText:originFocus?.textContent||'',searchTrigger:!!originFocus&&(originFocus.classList?.contains('workspace-search-entry')||!!originFocus.closest?.('.workspace-sidebar nav')&&(originFocus.textContent||'').trim()==='查词'),focusIndex:originFocus?Array.from(document.querySelectorAll?.('button,a,input,select,textarea')||[]).filter(e=>e.tagName===originFocus.tagName&&e.getAttribute('aria-label')===originFocus.getAttribute('aria-label')&&(e.textContent||'')===(originFocus.textContent||'')).indexOf(originFocus):-1};setSearchFrom(nav);navigate('search');return true;};
