 const pageDescriptions:Record<string,string>={today:`${new Intl.DateTimeFormat('zh-CN',{timeZone:profile.timezone,month:'long',day:'numeric'}).format(now)} · 每日计划 ${profile.dailyMinutes} 分钟`,train:'一次专心完成一组，再理解答案依据。',review:'词卡与题目是两条独立队列，完成分别记录。',progress:'以真实记录观察节奏；样题表现不换算正式分数。',resources:'选一份材料，按步骤完成，再记下实际学习。',settings:'四种气质，同一个学习空间。',backups:'学习、词库与模考各自备份，保留当前设备与账号范围。',art:'原创内容、通用词典和外站材料分别说明。'};
